/// <summary>
/// CB223_PalletRounding
/// Pallet rounding logic for a sales order.
/// </summary>
internal final class METSalesTablePalletRoundingProcess
{
    SalesId salesId;
}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <returns>New instance of <c>METSalesTablePalletRoundingProcess</c> class</returns>
static METSalesTablePalletRoundingProcess construct(SalesId _salesId)
{
    if (!_salesId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }
    
    return new METSalesTablePalletRoundingProcess(_salesId);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
protected void new(SalesId _salesId)
{
    salesId = _salesId;
}

    /// <summary>
    /// Run the sales order pallet rounding
    /// </summary>
    void run()
    {
        SalesLine salesLineLoop;
        InventDim inventDim;

        while select ItemId, CustAccount, SalesUnit, sum(SalesQty) 
            from salesLineLoop
                group by ItemId, CustAccount, SalesUnit
                join InventSiteId from inventDim
                group by InventSiteId
                where inventDim.inventDimId == salesLineLoop.InventDimId
                   && salesLineLoop.SalesId == salesId             
        {
            // Check 1: The sales order line site, item and customer match an active pallet rounding policy.
            METPalletRoundingPolicySearch search = METPalletRoundingPolicySearch::construct(salesLineLoop.CustAccount, inventDim.InventSiteId, salesLineLoop.ItemId);
            METPalletRoundingPolicyLine palletRoundingPolicyLine = search.search();

            if (palletRoundingPolicyLine)
            {
                // TODO add some validations here
                
                /*SalesQty palletQtyInventoryUOM = UnitOfMeasureConverter::convert(
                            1,
                            UnitOfMeasure::unitOfMeasureIdBySymbol("PL"),
                            UnitOfMeasure::unitOfMeasureIdBySymbol(salesLineLoop.inventTable().inventUnitId()),
                            NoYes::Yes,
                            InventTable::itemProduct(salesLineLoop.ItemId));*/
                
                // Check 3: Convert the Sales order line(s) quantity into the Inventory Unit of measure.
                InventQty salesLineInventQty = UnitOfMeasureConverter::convert(
                            salesLineLoop.SalesQty,
                            UnitOfMeasure::unitOfMeasureIdBySymbol(salesLineLoop.SalesUnit),
                            UnitOfMeasure::unitOfMeasureIdBySymbol(salesLineLoop.inventTable().inventUnitId()),
                            NoYes::Yes,
                            InventTable::itemProduct(salesLineLoop.ItemId));
                
                METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(salesLineLoop.ItemId, inventDim.InventSiteId);
                
                InventQty modQty = salesLineInventQty mod metInventItemOrderSetup.PalletQty;

                // Check 4: If the result percentage is equal or greater than the percentage defined in the pallet rounding policy, round up will be applied to the sales order line
                if (((modQty * 100)  / metInventItemOrderSetup.PalletQty) >= palletRoundingPolicyLine.RoundingPercentage)
                {
                    // If above checks are successful, apply the pallet rounding.
                    // Convert the new quantity from the item's inventory unit of measure to the sales order unit of measure and apply it to the original sales order line (not on the bonus stock line).
                    InventQty salesLineRoundedInventQty = salesLineInventQty + metInventItemOrderSetup.PalletQty - modQty;
                    InventQty salesLineDiffInventQty = salesLineRoundedInventQty - salesLineInventQty;

                    SalesQty salesLineRoundedSalesQty = UnitOfMeasureConverter::convert(
                            salesLineDiffInventQty,
                            UnitOfMeasure::unitOfMeasureIdBySymbol(salesLineLoop.inventTable().inventUnitId()),
                            UnitOfMeasure::unitOfMeasureIdBySymbol(salesLineLoop.SalesUnit),                            
                            NoYes::Yes,
                            InventTable::itemProduct(salesLineLoop.ItemId));

                    ttsbegin;
                    SalesLine salesLine = SalesLine::metFindBonusStock(salesId, salesLineLoop.ItemId, salesLineLoop.CustAccount, salesLineLoop.SalesUnit, inventDim.InventSiteId, NoYes::No, true);
                    SalesQty origSalesQty = salesLine.SalesQty;
                    
                    salesLine.SalesQty += salesLineRoundedSalesQty;
                    
                    // very important to call this to update inventTrans qty and remainder qty
                    salesLine.salesQtyModified();
                    salesLine.update();

                    METSalesLine metSalesLine = METSalesLine::find(salesLine.RecId, true);
                    metSalesLine.PalletRoundingApplied = NoYes::Yes;
                    metSalesLine.PalletRoundingOriginalQty = origSalesQty;
                    metSalesLine.PalletRoundingPolicyName = palletRoundingPolicyLine.METPalletRoundingPolicyHeader().PolicyName;
                    metSalesLine.PalletRoundingPercentage = palletRoundingPolicyLine.RoundingPercentage;

                    metSalesLine.update();
                    ttscommit;
                }
            }
        }
    }
